// Maps an original image path (/img/..., /images/...) to the WebP copy
// generated by scripts/optimize-images.mjs. Safe to use on the client.
export const WIDTHS = [800, 1600];

const OPTIMIZABLE = /^\/(img|images)\/.+\.(png|jpe?g|webp)$/i;

export function optimized(src, width = 1600) {
  if (!src || !OPTIMIZABLE.test(src)) return src;
  return `/_img${encodeURI(decodeURI(src))}.w${width}.webp`;
}
